from django.http import HttpResponse

def request_info(request):
    info = f'''
    <h2>请求信息</h2>
    <p>请求方法：{request.method}</p>
    <p>请求路径：{request.path}</p>
    <p>完整路径：{request.get_full_path()}</p>
    <p>是否是AJAX：{request.headers.get('X-Requested-With') == 'XMLHttpRequest'}</p>
    <p>用户IP：{request.META.get('REMOTE_ADDR')}</p>
    <p>用户代理：{request.META.get('HTTP_USER_AGENT')}</p>
    <p>引用页：{request.META.get('HTTP_REFERER', '直接访问')}</p>
    <p>Content-Type：{request.content_type}</p>
    '''
    return HttpResponse(info)

def get_headers(request):
    # 获取所有请求头
    headers = []
    for key, value in request.headers.items():
        headers.append(f'{key}: {value}')
    return HttpResponse('<br>'.join(headers))

def method_example(request):
    # 根据请求方法做不同处理
    if request.method == 'GET':
        # 显示表单
        return HttpResponse('这是GET请求，显示表单页面')
    elif request.method == 'POST':
        # 处理表单提交
        return HttpResponse('这是POST请求，处理表单数据')
    else:
        return HttpResponse('不支持的请求方法', status=405)

